// Called when a CR or LF is seen outside quotes. A CR is only a record
// terminator when immediately followed by LF, so it is held pending.
export function consumeLine(state, char) {
  if (char === '\r') {
    finishField(state);
    state.pendingCR = true;
    state.touched = true;
    return true;
  }
  if (char === '\n') {
    finishField(state);
    finishRecord(state);
    return true;
  }
  return false;
}

// Called for the character following a pending CR.
export function consumePendingCR(state, char) {
  if (char !== '\n') throw syntax('BARE_CR');
  state.pendingCR = false;
  finishRecord(state);
}
